const D={
"ros-domain-bridge":{no:"03.07",title:"ros_domain_bridge로 다른 Domain 연결",lead:"서로 격리된 ROS 2 DDS 도메인 사이에 브리지를 두고 필요한 토픽만 선택해 안전하게 중계합니다.",time:"70분",source:"https://drive.google.com/file/d/1iZNo7dQnAMGHPVwxhkmcz6_qrYj585BO/view",concepts:[["ros_domain_bridge","서로 다른 ROS_DOMAIN_ID 사이에서 지정한 토픽을 전달하는 브리지"],["from_domain / to_domain","브리지가 연결할 출발·도착 DDS 도메인 ID"],["Topic bridge","전체 그래프가 아니라 필요한 토픽만 골라 중계하는 방식"],["설정 파일","도메인과 중계 대상 토픽·타입을 재현 가능하게 선언하는 파일"]],steps:[["패키지 확인","Jazzy 환경에서 ros_domain_bridge 실행 파일과 도움말을 먼저 확인합니다.","source /opt/ros/jazzy/setup.bash\nros2 pkg executables | grep domain_bridge\nros2 run ros_domain_bridge domain_bridge --help"],["두 도메인 실행","서로 다른 터미널에서 Domain 1과 2의 노드를 실행해 격리 상태를 확인합니다.","# 터미널 1\nexport ROS_DOMAIN_ID=1\nros2 run demo_nodes_cpp talker\n# 터미널 2\nexport ROS_DOMAIN_ID=2\nros2 run demo_nodes_py listener"],["브리지 설정 작성","출발·도착 도메인과 중계할 토픽 이름·메시지 타입을 설정 파일에 명시합니다.","# 설정 개념 예시\nfrom_domain: 1\nto_domain: 2\ntopics:\n  /chatter:\n    type: std_msgs/msg/String"],["브리지 실행","도움말에서 확인한 옵션으로 설정 파일을 전달해 브리지 프로세스를 실행합니다.","ros2 run ros_domain_bridge domain_bridge --help\n# 설치된 버전의 옵션에 맞춰 설정 파일 지정"],["Domain 2에서 수신 확인","브리지 실행 전에는 보이지 않던 /chatter가 Domain 2에서 수신되는지 확인합니다.","export ROS_DOMAIN_ID=2\nros2 topic list\nros2 topic echo /chatter"],["중계 범위 검증","설정하지 않은 토픽은 넘어오지 않고 선택한 토픽만 전달되는지 양쪽에서 비교합니다.","ROS_DOMAIN_ID=1 ros2 topic list\nROS_DOMAIN_ID=2 ros2 topic list\nROS_DOMAIN_ID=2 ros2 topic info /chatter -v"]],check:["브리지 실행 전 두 도메인이 격리됨을 확인했다","설정한 토픽이 다른 도메인에서 수신됨을 확인했다","설정하지 않은 토픽은 중계되지 않음을 확인했다"],quiz:["중계할 토픽을 설정에서 제한하는 주된 이유는?","필요한 통신만 명시적으로 연결하기 위해",["도메인 ID를 없애기 위해","필요한 통신만 명시적으로 연결하기 위해","모든 노드를 한 프로세스로 만들기 위해"]]},
"ros-commands":{no:"02.01",title:"ROS 2 기초 명령",lead:"turtlesim을 직접 움직이며 노드·토픽·서비스·액션의 차이를 손으로 익힙니다.",time:"45–60분",source:"../lessons/02-01-ros-commands.html",concepts:[["Node","하나의 기능을 담당하는 ROS 2 실행 단위"],["Topic","발행·구독 기반의 비동기 스트림"],["Service","한 번의 요청에 한 번 응답하는 통신"],["Action","목표·피드백·결과를 갖는 장시간 작업"]],steps:[["환경과 시뮬레이터 실행","두 터미널에서 환경을 활성화하고 turtlesim과 키보드 조작 노드를 실행합니다.","source /opt/ros/jazzy/setup.bash\nros2 run turtlesim turtlesim_node\n# 새 터미널\nros2 run turtlesim turtle_teleop_key"],["그래프 관찰","실행 중인 노드와 인터페이스를 발견합니다.","ros2 node list\nros2 node info /turtlesim\nros2 topic list -t\nros2 service list\nros2 action list -t"],["메시지 정의 확인","값을 보내기 전에 인터페이스 구조부터 확인합니다.","ros2 interface show geometry_msgs/msg/Twist\nros2 topic echo /turtle1/pose"],["직접 발행","Twist 메시지를 1 Hz로 발행해 거북이를 원운동시킵니다.","ros2 topic pub -r 1 /turtle1/cmd_vel geometry_msgs/msg/Twist \"{linear: {x: 1.5}, angular: {z: 1.0}}\""],["서비스와 액션 비교","즉시 끝나는 reset과 진행 시간이 있는 rotate_absolute를 각각 호출합니다.","ros2 service call /reset std_srvs/srv/Empty \"{}\"\nros2 action send_goal --feedback /turtle1/rotate_absolute turtlesim/action/RotateAbsolute \"{theta: 1.57}\""]],check:["node list에서 turtlesim 노드를 찾았다","topic echo로 Pose가 바뀌는 것을 봤다","Topic·Service·Action의 용도를 설명할 수 있다"],quiz:["중간 피드백과 취소가 필요한 작업에 가장 알맞은 통신은?","Action",["Topic","Service","Action"]]},
"topics-python":{no:"02.02",title:"Python으로 토픽 다루기",lead:"rclpy로 Subscriber와 Publisher를 작성하고 콜백·spin·QoS의 역할을 연결합니다.",time:"60분",source:"../lessons/02-02-topics-python.html",concepts:[["Publisher","메시지를 토픽에 발행하는 주체"],["Subscriber","토픽 메시지를 콜백으로 받는 주체"],["spin","콜백을 처리하는 이벤트 루프"],["QoS","신뢰성·버퍼 등 통신 품질 정책"]],steps:[["실습 대상 실행","turtlesim을 켜고 Pose 타입과 토픽을 확인합니다.","ros2 run turtlesim turtlesim_node\nros2 topic type /turtle1/pose\nros2 interface show turtlesim/msg/Pose"],["Subscriber 작성","노드·구독·콜백을 만들고 spin으로 메시지를 계속 처리합니다.","import rclpy\nfrom turtlesim.msg import Pose\nrclpy.init()\nnode = rclpy.create_node('pose_reader')\ndef cb(msg): print(msg.x, msg.y, msg.theta)\nsub = node.create_subscription(Pose, '/turtle1/pose', cb, 10)\nrclpy.spin(node)"],["Publisher 작성","Twist 메시지를 만들고 타이머 콜백에서 주기적으로 발행합니다.","from geometry_msgs.msg import Twist\npub = node.create_publisher(Twist, '/turtle1/cmd_vel', 10)\ndef tick():\n    msg = Twist(); msg.linear.x = 1.0; msg.angular.z = .8\n    pub.publish(msg)\ntimer = node.create_timer(.1, tick)"],["연결 확인","토픽 이름과 타입이 양쪽에서 같은지 그래프로 확인합니다.","rqt_graph\nros2 topic info /turtle1/cmd_vel -v"],["정리","노드와 rclpy 컨텍스트를 순서대로 종료합니다.","node.destroy_node()\nrclpy.shutdown()"]],check:["Pose 콜백이 반복 호출됐다","Publisher로 거북이를 움직였다","spin과 spin_once의 차이를 설명할 수 있다"],quiz:["콜백이 전혀 호출되지 않을 때 가장 먼저 확인할 것은?","spin 실행 여부",["타이머 주기","spin 실행 여부","노드 색상"]]},
"services":{no:"02.03",title:"서비스 클라이언트",lead:"turtlesim의 teleport_absolute를 호출하며 Request·Response와 Future 처리 흐름을 배웁니다.",time:"40분",source:"../lessons/02-03-services.html",concepts:[["Request","클라이언트가 서버에 보내는 입력"],["Response","서버가 작업 후 반환하는 출력"],["Future","비동기 결과가 나중에 담기는 객체"],["wait_for_service","서버 준비 여부를 확인하는 안전장치"]],steps:[["서비스 발견","이름과 타입, 요청 필드를 차례로 찾습니다.","ros2 service list\nros2 service type /turtle1/teleport_absolute\nros2 interface show turtlesim/srv/TeleportAbsolute"],["클라이언트 생성","서비스 타입과 정확한 이름으로 클라이언트를 만듭니다.","from turtlesim.srv import TeleportAbsolute\nclient = node.create_client(TeleportAbsolute, '/turtle1/teleport_absolute')\nclient.wait_for_service(timeout_sec=2.0)"],["요청 작성","Request 객체의 필드를 채웁니다.","req = TeleportAbsolute.Request()\nreq.x = 5.5; req.y = 5.5; req.theta = 1.57"],["비동기 호출","Future가 완료될 때까지 executor가 이벤트를 처리하게 합니다.","future = client.call_async(req)\nrclpy.spin_until_future_complete(node, future)\nprint(future.result())"],["검증","거북이 위치가 바뀌고 터미널 호출도 같은 결과인지 비교합니다.","ros2 service call /turtle1/teleport_absolute turtlesim/srv/TeleportAbsolute \"{x: 2.0, y: 3.0, theta: 0.0}\""]],check:["service type과 interface를 스스로 찾았다","Future 결과를 확인했다","토픽과 서비스의 차이를 설명할 수 있다"],quiz:["call_async()가 즉시 반환하는 객체는?","Future",["Response","Future","Publisher"]]},
"package-topics":{no:"02.04",title:"패키지와 토픽 노드",lead:"워크스페이스에 Python 패키지를 만들고 Subscriber·Publisher를 실행 가능한 노드로 배포합니다.",time:"70분",source:"../lessons/02-04-package-topics.html",concepts:[["Workspace","src·build·install·log로 구성되는 작업 공간"],["Package","코드와 메타데이터를 묶는 배포 단위"],["Entry point","ros2 run 이름과 Python main을 연결"],["colcon","의존 순서대로 패키지를 빌드하는 도구"]],steps:[["패키지 생성","워크스페이스 src 아래에 ament_python 패키지를 만듭니다.","mkdir -p ~/ros2_ws/src && cd ~/ros2_ws/src\nros2 pkg create --build-type ament_python my_topic"],["노드 작성","Node를 상속하고 create_subscription 또는 create_publisher를 구성합니다.","# my_topic/subscriber.py\n# class TopicSubscriber(Node): ...\n# def main(): rclpy.init(); rclpy.spin(TopicSubscriber())"],["실행 등록","setup.py의 console_scripts에 실행 이름을 연결합니다.","entry_points={\n 'console_scripts': [\n  'subscriber = my_topic.subscriber:main',\n  'publisher = my_topic.publisher:main',\n ]\n}"],["빌드와 source","워크스페이스 루트에서 빌드한 뒤 install 환경을 현재 셸에 반영합니다.","cd ~/ros2_ws\ncolcon build --symlink-install\nsource install/setup.bash"],["실행·관찰","각 노드를 별도 터미널에서 실행하고 그래프를 확인합니다.","ros2 run my_topic subscriber\nros2 run my_topic publisher\nrqt_graph"]],check:["ament_python 패키지를 만들었다","ros2 run으로 두 노드를 실행했다","setup.py 변경 뒤 재빌드가 필요한 이유를 안다"],quiz:["ros2 run의 실행 이름을 등록하는 파일은?","setup.py",["package.xml","setup.py","README.md"]]},
"custom-messages":{no:"02.05",title:"커스텀 메시지와 서비스",lead:".msg와 .srv를 직접 정의하고 빌드하여 토픽·서비스에 사용하는 전체 파이프라인을 익힙니다.",time:"90분",source:"../lessons/02-05-custom-messages.html",concepts:[[".msg","토픽에서 주고받을 필드 구조"],[".srv","---로 구분한 Request·Response 구조"],["rosidl","인터페이스 정의에서 언어별 코드를 생성"],["재빌드","정의 변경 후 생성 코드를 다시 만드는 단계"]],steps:[["인터페이스 파일 작성","별도 인터페이스 패키지의 msg·srv 폴더에 정의합니다.","# msg/CmdAndPoseVel.msg\ngeometry_msgs/Twist cmd\nturtlesim/Pose pose\n\n# srv/MultiSpawn.srv\nint32 count\n---\nbool success"],["빌드 등록","CMakeLists.txt의 rosidl_generate_interfaces와 package.xml 의존성을 추가합니다.","rosidl_generate_interfaces(${PROJECT_NAME}\n  \"msg/CmdAndPoseVel.msg\"\n  \"srv/MultiSpawn.srv\"\n  DEPENDENCIES geometry_msgs turtlesim\n)"],["선택 빌드","정의 패키지를 빌드하고 반드시 새 인터페이스를 source합니다.","colcon build --packages-select my_interfaces\nsource install/setup.bash\nros2 interface show my_interfaces/msg/CmdAndPoseVel"],["코드에서 사용","생성된 클래스를 import해 메시지 객체 또는 서비스 Request·Response로 사용합니다.","from my_interfaces.msg import CmdAndPoseVel\nfrom my_interfaces.srv import MultiSpawn"],["통합 검증","echo·service call·rqt_graph로 데이터와 연결을 모두 확인합니다.","ros2 topic echo /cmd_and_pose\nros2 service list\nrqt_graph"]],check:["msg와 srv 정의를 작성했다","interface show에서 생성 결과를 확인했다","정의 변경 후 build와 source를 반복했다"],quiz:[".srv에서 Request와 Response를 나누는 표시는?","---",["===","---",":::"]]},
"actions":{no:"02.06",title:"ROS 2 액션",lead:"Goal·Feedback·Result를 정의하고 멀티스레드 액션 서버로 장시간 로봇 작업을 구현합니다.",time:"75분",source:"../lessons/02-06-actions.html",concepts:[["Goal","클라이언트가 서버에 전달하는 목표"],["Feedback","작업 중 반복해서 보내는 진행 상태"],["Result","작업 종료 시 반환하는 최종 값"],["Cancel","진행 중인 목표를 안전하게 중단"]],steps:[["액션 정의","Goal, Result, Feedback 세 영역을 순서대로 정의합니다.","# action/DistTurtle.action\nfloat32 distance\n---\nbool success\n---\nfloat32 remaining"],["인터페이스 생성","CMakeLists와 package.xml에 action을 등록하고 빌드합니다.","colcon build --packages-select my_interfaces\nsource install/setup.bash\nros2 interface show my_interfaces/action/DistTurtle"],["서버 구현","ActionServer의 execute_callback에서 진행 값을 발행하고 결과를 반환합니다.","self.server = ActionServer(self, DistTurtle, 'dist_turtle', self.execute_cb)\n# goal_handle.publish_feedback(feedback)\n# goal_handle.succeed(); return result"],["콜백 병렬화","액션 수행 중 subscriber도 돌아야 한다면 재진입 콜백 그룹과 멀티스레드 실행기를 씁니다.","group = ReentrantCallbackGroup()\nexecutor = MultiThreadedExecutor()\nexecutor.add_node(node); executor.spin()"],["목표 전송","서버를 먼저 실행하고 피드백 옵션으로 진행 상태를 확인합니다.","ros2 action list -t\nros2 action send_goal --feedback /dist_turtle my_interfaces/action/DistTurtle \"{distance: 2.0}\""]],check:["Goal·Feedback·Result를 정의했다","실시간 Feedback을 확인했다","블로킹 콜백 문제와 해결책을 설명할 수 있다"],quiz:["액션 실행 중 다른 subscriber도 처리하려면?","MultiThreadedExecutor",["SingleThreadedExecutor","MultiThreadedExecutor","spin_once 제거"]]},
"parameters":{no:"02.07",title:"파라미터 다루기",lead:"코드 수정 없이 노드 동작을 조정하고 YAML과 콜백으로 설정을 지속·반영합니다.",time:"45분",source:"../lessons/02-07-parameters.html",concepts:[["Parameter","노드가 런타임에 노출하는 설정값"],["declare","파라미터 이름·기본값을 공개"],["Callback","변경을 검증하고 내부 상태에 반영"],["YAML","설정 묶음을 저장·재사용하는 형식"]],steps:[["터미널 탐색","실행 중인 노드의 파라미터를 조회하고 변경합니다.","ros2 param list\nros2 param get /turtlesim background_r\nros2 param set /turtlesim background_r 30"],["코드에 선언","자주 바뀌는 값을 하드코딩하지 않고 파라미터로 선언합니다.","self.declare_parameter('speed', 1.0)\nself.speed = self.get_parameter('speed').value"],["변경 콜백","런타임 set이 실제 동작에 반영되도록 콜백을 등록합니다.","self.add_on_set_parameters_callback(self.on_params)\n# 유효성 검사 후 SetParametersResult(successful=True)"],["저장과 복원","현재 설정을 YAML로 저장하고 다시 로드합니다.","ros2 param dump /my_node --output-dir config\nros2 param load /my_node config/my_node.yaml"],["GUI 조정","rqt에서 Dynamic Reconfigure 플러그인을 열어 값을 바꾸고 동작을 봅니다.","rqt\n# Plugins → Configuration → Dynamic Reconfigure"]],check:["파라미터 값을 CLI로 변경했다","dump한 YAML을 다시 load했다","선언과 변경 콜백의 역할 차이를 안다"],quiz:["set은 성공했는데 로봇 동작이 그대로일 때 필요한 것은?","파라미터 변경 콜백",["새 토픽","파라미터 변경 콜백","서비스 삭제"]]},
"debug-launch":{no:"02.08",title:"관찰·디버깅과 Launch",lead:"로그·rqt·rosbag으로 문제를 재현하고 launch 파일로 여러 노드를 한 번에 실행합니다.",time:"70분",source:"../lessons/02-08-debug-roslaunch.html",concepts:[["Logging","레벨과 문맥이 있는 진단 기록"],["rqt","그래프·플롯·콘솔·모니터 GUI 도구"],["rosbag","토픽 데이터를 기록하고 재생"],["Launch","노드·파라미터·리맵을 묶어 실행"]],steps:[["구조화 로그","print 대신 노드 logger와 적절한 레벨을 사용합니다.","self.get_logger().debug('callback entered')\nself.get_logger().info('goal accepted')\nself.get_logger().warn('slow response')\nself.get_logger().error('request failed')"],["시각 관찰","연결은 graph, 수치는 plot, 로그는 console로 나눠 봅니다.","rqt_graph\nrqt_plot /turtle1/pose/x\nrqt_console"],["기록과 재생","문제가 발생한 토픽을 저장해 같은 입력으로 반복 테스트합니다.","ros2 bag record /turtle1/pose /turtle1/cmd_vel\nros2 bag info <bag-directory>\nros2 bag play <bag-directory>"],["Launch 작성","Python launch 파일에 여러 Node action과 파라미터를 선언합니다.","from launch import LaunchDescription\nfrom launch_ros.actions import Node\ndef generate_launch_description():\n return LaunchDescription([Node(package='my_pkg', executable='server')])"],["설치·실행","launch 파일이 install에 복사되도록 setup.py data_files를 등록한 뒤 빌드합니다.","colcon build --packages-select my_pkg\nsource install/setup.bash\nros2 launch my_pkg system.launch.py"]],check:["로그 레벨을 구분해 사용했다","bag을 기록하고 재생했다","launch로 두 개 이상의 노드를 실행했다"],quiz:["같은 센서 입력으로 버그를 반복 재현할 때 가장 유용한 도구는?","rosbag",["rqt_graph","rosbag","ros2 node list"]]},
"tf-pose":{no:"03.01",title:"TF와 Pose 발행",lead:"TransformStamped를 시간과 함께 발행하고 Quaternion 자세를 RViz에서 검증합니다.",time:"70분",source:"../lessons/03-01-tf-pose.html",concepts:[["Frame","위치와 방향을 측정하는 기준 좌표계"],["TF2","프레임 사이 변환을 시간축과 함께 관리"],["TransformStamped","부모·자식·시간·이동·회전을 담는 메시지"],["Quaternion","짐벌락 없이 3차원 회전을 표현하는 네 값"]],steps:[["브로드캐스터 생성","Node 안에 TransformBroadcaster와 주기 타이머를 만듭니다.","self.br = tf2_ros.TransformBroadcaster(self)\nself.timer = self.create_timer(0.1, self.timer_callback)"],["변환 구성","부모 world에서 자식 moving_frame으로 향하는 변환을 채웁니다.","t = TransformStamped()\nt.header.stamp = self.get_clock().now().to_msg()\nt.header.frame_id = 'world'\nt.child_frame_id = 'moving_frame'"],["원 궤도 위치","시간 변수로 x·y를 갱신해 반지름 2 m 원을 만듭니다.","self.t += 0.05\nt.transform.translation.x = 2.0 * math.cos(self.t)\nt.transform.translation.y = 2.0 * math.sin(self.t)"],["자세 추가","원점을 바라보는 yaw를 계산해 Quaternion으로 변환합니다.","yaw = math.atan2(-y, -x)\nq = quaternion_from_euler(0.0, 0.0, yaw)\nt.transform.rotation.x, t.transform.rotation.y, t.transform.rotation.z, t.transform.rotation.w = q\nself.br.sendTransform(t)"],["RViz 검증","Fixed Frame을 world로 바꾸고 TF display를 추가합니다.","rviz2\n# Global Options → Fixed Frame: world\n# Add → TF"]],check:["world→moving_frame 변환을 발행했다","RViz에서 원 궤도를 확인했다","Euler와 Quaternion의 장단점을 설명할 수 있다"],quiz:["TransformStamped의 frame_id가 의미하는 것은?","부모 프레임",["자식 프레임","부모 프레임","노드 이름"]]},
"child-frame":{no:"03.02",title:"Child Frame 확장",lead:"상대 좌표로 자식 프레임을 붙이고 하나의 브로드캐스터에서 TF 트리 전체를 관리합니다.",time:"50분",source:"../lessons/03-02-child-frame.html",concepts:[["Parent","자식 좌표를 해석하는 기준 프레임"],["Child","부모에 대한 상대 변환으로 정의되는 프레임"],["TF Tree","world→moving→child처럼 연결된 비순환 구조"],["Relative pose","전역값 대신 부모 기준으로 표현한 위치·자세"]],steps:[["트리 설계","이번 목표를 world → moving_frame → child_frame으로 먼저 그립니다.","world\n└── moving_frame  (반지름 2 m, 속도 1×)\n    └── child_frame (반지름 1 m, 속도 2×)"],["자식 변환 지정","핵심은 부모가 world가 아니라 moving_frame이라는 점입니다.","t.header.frame_id = 'moving_frame'\nt.child_frame_id = 'child_frame'"],["상대 운동 계산","child_frame은 부모 원점 주위를 더 빠르게 돌도록 계산합니다.","angle = 2.0 * self.t\nx = math.cos(angle); y = math.sin(angle)\nyaw = math.atan2(-y, -x)"],["헬퍼로 통합","반복되는 TransformStamped 생성을 send_tf 함수로 추출합니다.","def send_tf(self, parent, child, x, y, z, yaw):\n    # stamp, frame ids, translation, quaternion 설정\n    self.br.sendTransform(t)\n\nself.send_tf('world','moving_frame', x1,y1,0,yaw1)\nself.send_tf('moving_frame','child_frame', x2,y2,0,yaw2)"],["트리 검증","한 노드만 실행하고 RViz와 frames 도구로 계층을 확인합니다.","ros2 run my_tf combined_frame\nrviz2\nros2 run tf2_tools view_frames"],["확장 실험","child_frame 아래 sensor_frame을 한 개 더 추가하고 RViz에서 결과를 확인합니다.","self.send_tf('child_frame','sensor_frame', 0.4,0.0,0.2,0.0)"]],check:["부모와 자식 frame_id를 올바르게 지정했다","하나의 브로드캐스터로 여러 TF를 발행했다","상대 좌표가 전역 좌표로 합성되는 과정을 설명할 수 있다"],quiz:["child_frame의 부모를 moving_frame으로 만들려면 어디에 적어야 하나?","header.frame_id",["child_frame_id","header.frame_id","node name"]]},
"tf-listener":{no:"03.03",title:"TF Frame 구독과 변환 활용",lead:"TransformListener로 TF를 수신하고 world와 child_frame 사이의 거리 정보를 계산해 토픽으로 발행합니다.",time:"55분",source:"https://drive.google.com/file/d/1UnnRwgSL42rtK8RvMQCRZ8cDnEOiEZZJ/view",concepts:[["Buffer","수신한 TF 변환을 일정 시간 보관하는 캐시"],["TransformListener","/tf와 /tf_static을 구독해 Buffer를 채우는 객체"],["lookup_transform","target 기준 source의 최신 변환을 조회"],["TransformException","프레임이나 시간 데이터가 없을 때 처리할 예외"]],steps:[["Listener 준비","노드 초기화에서 Buffer와 Listener를 함께 생성합니다.","self.tf_buffer = tf2_ros.Buffer()\nself.tf_listener = tf2_ros.TransformListener(self.tf_buffer, self)"],["거리 토픽 준비","계산 결과를 Float32 토픽으로 발행하고 10 Hz 타이머를 만듭니다.","self.dist_pub = self.create_publisher(Float32, 'distance_world_child', 10)\nself.timer = self.create_timer(0.1, self.timer_callback)"],["최신 변환 조회","world를 기준으로 child_frame의 최신 변환을 요청합니다.","transform = self.tf_buffer.lookup_transform(\n    'world', 'child_frame', rclpy.time.Time()\n)"],["거리 계산·발행","translation의 x·y·z로 3차원 유클리드 거리를 계산합니다.","p = transform.transform.translation\nmsg = Float32()\nmsg.data = math.sqrt(p.x**2 + p.y**2 + p.z**2)\nself.dist_pub.publish(msg)"],["예외 처리","TF가 아직 도착하지 않은 시작 시점에도 노드가 종료되지 않게 합니다.","try:\n    transform = self.tf_buffer.lookup_transform(...)\nexcept tf2_ros.TransformException as ex:\n    self.get_logger().debug(str(ex))"],["빌드와 확인","entry point를 등록한 뒤 브로드캐스터와 listener를 각각 실행합니다.","colcon build --packages-select my_tf\nsource install/setup.bash\nros2 run my_tf combined_frame\nros2 run my_tf distance_world_child_publisher\nros2 topic echo /distance_world_child"]],check:["Buffer와 Listener를 함께 생성했다","target과 source 순서를 설명할 수 있다","거리 토픽이 움직임에 따라 변하는 것을 확인했다"],quiz:["lookup_transform('world','child_frame', time)에서 target frame은?","world",["child_frame","world","time"]]},
"tf-rviz":{no:"03.04",title:"TF 결과를 RViz2에 시각화",lead:"Marker·PoseStamped·Path를 이용해 프레임의 이동 경로와 거리 정보를 RViz2에 표현합니다.",time:"75분",source:"https://drive.google.com/file/d/1JJWiP80WCfeY33NJY8vtmZpFvin81OJ6/view",concepts:[["Marker.LINE_STRIP","Point 목록을 순서대로 연결하는 자유로운 선 시각화"],["PoseStamped","frame과 시간을 포함한 위치·자세 한 개"],["Path","PoseStamped 목록으로 구성된 내비게이션 경로"],["Sliding window","오래된 값을 제거해 최근 N개 데이터만 유지"]],steps:[["Marker 퍼블리셔","world 기준 LINE_STRIP Marker를 발행할 준비를 합니다.","self.marker_pub = self.create_publisher(Marker, 'frame_trail', 10)\nmarker.header.frame_id = 'world'\nmarker.ns = 'frame_trail'; marker.id = 0\nmarker.type = Marker.LINE_STRIP"],["좌표를 선으로 변환","TF에서 얻은 위치를 Point로 만들고 points 배열에 추가합니다.","p = Point()\np.x, p.y, p.z = x, y, z\nself.positions.append(p)\nmarker.points = self.positions\nmarker.scale.x = 0.02\nmarker.color.r = 1.0; marker.color.a = 1.0"],["경로 길이 제한","무한 누적을 막고 최근 경로만 꼬리처럼 유지합니다.","self.positions.append(p)\nif len(self.positions) > self.max_points:\n    self.positions.pop(0)"],["Path로 표현","TF 변환을 PoseStamped로 옮긴 뒤 Path의 poses에 추가합니다.","pose = PoseStamped()\npose.header.frame_id = 'world'\npose.pose.position.x = x\npose.pose.orientation = transform.transform.rotation\nself.path_msg.poses.append(pose)\nself.path_pub.publish(self.path_msg)"],["거리 텍스트 표시","TEXT_VIEW_FACING Marker로 카메라를 향하는 거리 문자열을 표시합니다.","marker.type = Marker.TEXT_VIEW_FACING\nmarker.text = f'{distance:.2f} m'\nmarker.scale.z = 0.25\nmarker.color.a = 1.0"],["RViz 설정","TF, Marker, Path 디스플레이를 추가하고 각각의 토픽을 선택합니다.","ros2 run my_tf combined_frame\nros2 run my_tf frame_trail_publisher_nav_3\nrviz2\n# Fixed Frame: world\n# Add: TF, Marker, Path"]],check:["Marker와 Path의 데이터 구조 차이를 안다","최근 N개 경로만 남도록 제한했다","RViz에서 경로와 거리 텍스트를 확인했다"],quiz:["Path 메시지에 누적되는 요소의 타입은?","PoseStamped",["Point","PoseStamped","TransformBroadcaster"]]},
"domain-id":{no:"03.05",title:"서로 다른 ROS Domain ID에 접근",lead:"DDS 도메인으로 ROS 2 시스템을 격리하고 multiprocessing으로 한 스크립트에서 여러 도메인을 동시에 제어합니다.",time:"70분",source:"https://drive.google.com/file/d/11jutQNU03NtC2XgfUpCts-PTF09YDdgR/view",concepts:[["ROS_DOMAIN_ID","같은 ID의 노드끼리만 발견·통신하게 만드는 DDS 도메인 식별자"],["ROS_LOCALHOST_ONLY","DDS 통신 범위를 현재 컴퓨터로 제한하는 환경변수"],["domain_id 인자","rclpy.init에서 현재 프로세스가 참여할 도메인을 코드로 지정"],["multiprocessing","각 도메인에 독립적인 rclpy 컨텍스트를 제공하는 프로세스 분리 방식"]],steps:[["환경변수로 도메인 분리","터미널마다 다른 DOMAIN_ID를 설정하고 현재 값을 확인합니다.","source /opt/ros/jazzy/setup.bash\nexport ROS_DOMAIN_ID=1\necho $ROS_DOMAIN_ID\n# 다른 터미널: export ROS_DOMAIN_ID=2"],["통신 격리 확인","서로 다른 도메인의 listener와 talker는 발견되지 않음을 확인한 뒤 ID를 맞춥니다.","# Domain 1 터미널\nros2 run demo_nodes_py listener\n# Domain 2 터미널\nros2 run demo_nodes_cpp talker\n# talker 터미널을 Domain 1로 변경 후 다시 실행"],["로컬 통신으로 제한","외부 네트워크 노드와의 간섭을 막아야 할 때 localhost 제한을 함께 적용합니다.","export ROS_LOCALHOST_ONLY=1\necho $ROS_LOCALHOST_ONLY"],["도메인별 프로세스 초기화","각 자식 프로세스에서 별도의 domain_id로 rclpy를 초기화합니다.","def publisher_process(domain_id, start, increment):\n    rclpy.init(args=[], domain_id=domain_id)\n    node = DomainPublisher(domain_id, start, increment)\n    try:\n        rclpy.spin(node)\n    finally:\n        node.destroy_node()\n        rclpy.shutdown()"],["두 도메인 동시 발행","Domain 1에는 홀수, Domain 2에는 짝수를 발행하는 프로세스를 동시에 실행합니다.","p1 = multiprocessing.Process(target=publisher_process, args=(1, 1, 2))\np2 = multiprocessing.Process(target=publisher_process, args=(2, 2, 2))\np1.start(); p2.start()\np1.join(); p2.join()"],["도메인별 결과 검증","각 도메인의 /id_test를 구독해 서로 다른 수열만 도착하는지 확인합니다.","# Domain 1 터미널\nros2 topic echo /id_test\n# Domain 2 터미널\nros2 topic echo /id_test\n# Domain 1: 1,3,5... / Domain 2: 2,4,6..."]],check:["다른 DOMAIN_ID의 노드가 서로 발견되지 않음을 확인했다","ROS_LOCALHOST_ONLY와 DOMAIN_ID의 역할 차이를 설명할 수 있다","각 자식 프로세스에서 rclpy.init을 독립적으로 호출했다"],quiz:["한 프로그램에서 여러 ROS 도메인을 동시에 사용하기 위해 필요한 구조는?","도메인별 독립 프로세스",["하나의 스레드","도메인별 독립 프로세스","노드 이름 변경"]]},
"multi-domain-turtlesim":{no:"03.06",title:"서로 다른 Domain ID의 turtlesim 제어",lead:"하나의 Python 프로그램에서 서로 다른 DDS 도메인의 turtlesim을 토픽·서비스·액션으로 각각 제어합니다.",time:"90분",source:"https://drive.google.com/file/d/1M1Je9A0mWNiBXAQRiFPzkPNJ9XgcvHSM/view",concepts:[["Topic","cmd_vel을 지속 발행해 거북이의 선속도와 각속도를 제어"],["Service","teleport_absolute 요청으로 거북이를 지정 좌표에 한 번 이동"],["Action","rotate_absolute 목표를 보내고 수락·피드백·결과를 처리"],["multiprocessing","도메인마다 독립된 rclpy 컨텍스트를 실행하는 프로세스 구조"]],steps:[["두 도메인의 turtlesim 실행","Domain 1과 Domain 2 터미널에서 각각 turtlesim을 실행합니다.","# 터미널 1\nexport ROS_DOMAIN_ID=1\nros2 run turtlesim turtlesim_node\n# 터미널 2\nexport ROS_DOMAIN_ID=2\nros2 run turtlesim turtlesim_node"],["토픽으로 서로 다르게 회전","각 프로세스에서 cmd_vel을 발행해 Domain 1은 시계방향, Domain 2는 반시계방향으로 원운동시킵니다.","rclpy.init(args=[], domain_id=domain_id)\nmsg = Twist()\nmsg.linear.x = 1.0\nmsg.angular.z = angular_speed\npublisher.publish(msg)\n# Process args: (1, -1.0), (2, 1.0)"],["서비스로 서로 다른 위치 이동","teleport_absolute 요청의 x 좌표를 도메인마다 다르게 지정합니다.","client = node.create_client(TeleportAbsolute, '/turtle1/teleport_absolute')\nrequest = TeleportAbsolute.Request()\nrequest.x = target_x\nrequest.y = 5.544\nrequest.theta = 0.0\nfuture = client.call_async(request)"],["액션으로 서로 다른 방향 회전","rotate_absolute 액션에 Domain 1은 1.57, Domain 2는 4.71 라디안을 목표로 보냅니다.","client = ActionClient(node, RotateAbsolute, '/turtle1/rotate_absolute')\ngoal = RotateAbsolute.Goal()\ngoal.theta = target_theta\ngoal_future = client.send_goal_async(goal)\n# targets: (1, 1.57), (2, 4.71)"],["세 프로그램 실행","turtlesim 두 개를 유지한 상태에서 토픽·서비스·액션 예제를 하나씩 실행합니다.","python3 domain_test_turtle.py\npython3 domain_test_service.py\npython3 domain_test_action.py"],["결과 비교","토픽은 반복 제어, 서비스는 일회성 위치 변경, 액션은 목표 수행과 결과 반환이라는 차이를 확인합니다.","ros2 topic info /turtle1/cmd_vel\nros2 service type /turtle1/teleport_absolute\nros2 action info /turtle1/rotate_absolute"]],check:["두 DOMAIN_ID에서 turtlesim을 동시에 실행했다","토픽·서비스·액션 예제를 각각 실행해 결과를 확인했다","세 통신 방식의 실행 흐름과 적합한 용도를 설명할 수 있다"],quiz:["목표 수행 중 피드백과 결과가 필요한 회전 명령에 가장 적합한 방식은?","Action",["Topic","Service","Action"]]}
};
D["ros-domain-bridge"]={no:"03.07",title:"3개 Domain을 하나의 브리지로 연결",lead:"Domain 1의 /chatter를 Domain 2에서는 /chitter로 remap하고, Domain 3에서는 /chatter 그대로 받아 하나의 domain_bridge 설정으로 검증합니다.",time:"60분",source:"https://drive.google.com/file/d/1iZNo7dQnAMGHPVwxhkmcz6_qrYj585BO/view",concepts:[["전역 from_domain","출발 Domain 1을 한 번만 선언하고 각 토픽 항목에서 도착 Domain을 따로 지정합니다."],["토픽별 to_domain","첫 번째 chatter는 Domain 2, 두 번째 chatter는 Domain 3으로 전달됩니다."],["remap: chitter","첫 번째 경로만 도착 토픽 이름을 /chatter에서 /chitter로 바꿉니다."],["reversed 주석","#reversed: true는 주석이므로 실행되지 않습니다. 주석을 제거할 때만 해당 경로 방향이 반대가 됩니다."]],steps:[["통신 구조 설계","한 talker의 메시지를 Domain 2와 3으로 보내되 Domain 2에서만 토픽 이름을 바꿉니다.","Domain 1 /chatter\n├─ Domain 2 /chitter  (remap)\n└─ Domain 3 /chatter  (이름 유지)"],["최종 three_domain_bridge 작성","출발 Domain은 전역에 한 번 선언하고, 두 chatter 항목에 각각 도착 Domain을 지정합니다. 들여쓰기는 Tab이 아닌 공백입니다.","name: three_domain_bridge\n\nfrom_domain: 1\n\ntopics:\n  chatter:\n    type: std_msgs/msg/String\n    to_domain: 2\n    remap: chitter\n    #reversed: true\n  chatter:\n    type: std_msgs/msg/String\n    to_domain: 3"],["브리지 실행","브리지 실행 터미널의 현재 ID가 17이어도 각 연결은 YAML에 지정한 1·2·3으로 생성됩니다.","source /opt/ros/jazzy/setup.bash\nros2 run domain_bridge domain_bridge ~/three_domain_bridge"],["Domain 1 talker 실행","첫 번째 터미널에서 ID 1을 선택하고 기본 /chatter talker를 실행합니다.","export ROS_DOMAIN_ID=1\nros2 run demo_nodes_cpp talker"],["Domain 2에서 remap 결과 확인","두 번째 터미널에서는 echo로 /chitter에 들어오는 String 메시지를 직접 확인합니다.","export ROS_DOMAIN_ID=2\nros2 topic list -t\nros2 topic echo /chitter"],["Domain 3 listener 실행","세 번째 터미널은 /chatter를 그대로 구독하므로 별도 remap 없이 listener를 실행합니다.","export ROS_DOMAIN_ID=3\nros2 run demo_nodes_py listener"],["세 결과 비교","talker의 Hello World 번호가 Domain 2의 echo와 Domain 3의 listener에서 같은 순서로 나타나는지 비교합니다.","# Domain 1: Publishing: 'Hello World: 1'\n# Domain 2: data: 'Hello World: 1' (/chitter)\n# Domain 3: I heard: [Hello World: 1] (/chatter)"]],check:["전역 from_domain: 1을 한 번만 선언했다","각 chatter에 to_domain: 2와 3을 지정했다","Domain 2의 /chitter echo에서 Hello World를 확인했다","Domain 3의 기본 listener에서 같은 메시지를 확인했다"],quiz:["주석 처리된 #reversed: true가 현재 통신 방향에 미치는 영향은?","영향이 없다",["Domain 2에서 1로 뒤집힌다","영향이 없다","두 방향으로 전달된다"]]};
D["ros-domain-bridge"].concepts.push(["domain_bridge 방식","브리지 노드가 한 Domain에서 토픽을 구독하고 다른 Domain에 다시 발행합니다. YAML 설정만으로 토픽 연결·remap이 간단합니다."],["멀티프로세스 방식","각 프로세스가 rclpy.init(domain_id=...)으로 서로 다른 Domain에 직접 참여하고 Queue·Pipe로 프로세스 사이 데이터를 전달합니다."],["서비스의 타입 제약","토픽은 타입 이름 문자열로 동적 연결할 수 있지만 서비스 브리지 API는 C++ 템플릿 타입을 요구해 일반 YAML 실행 파일만으로 처리하기 어렵습니다."],["액션의 복합 구조","액션 하나는 send_goal·get_result·cancel_goal 서비스와 feedback·status 토픽을 함께 사용하므로 모든 내부 인터페이스와 QoS를 맞춰야 합니다."]);
D["ros-domain-bridge"].steps.splice(1,0,["두 방식의 구조 비교","토픽만 단순 중계하면 domain_bridge가 편리하지만 서비스·액션까지 제어하려면 Domain별 프로세스가 일반 ROS 2 API를 직접 사용하는 멀티프로세스 프록시가 안정적입니다.","# domain_bridge\nDomain 1 topic → bridge subscribe/publish → Domain 2 topic\n\n# multiprocessing proxy\nDomain 1 process ↔ Queue/Pipe ↔ Domain 2 process"],["왜 멀티프로세스를 사용하는가","하나의 rclpy 컨텍스트는 하나의 Domain에 참여합니다. 프로세스를 분리하면 각자 독립된 context와 domain_id를 갖고 Publisher·Service Client·Action Client API를 그대로 사용할 수 있습니다.","def worker(domain_id):\n    rclpy.init(args=[], domain_id=domain_id)\n    node = DomainWorker()\n    rclpy.spin(node)\n\np1 = multiprocessing.Process(target=worker, args=(1,))\np2 = multiprocessing.Process(target=worker, args=(2,))"],["서비스가 단순 YAML로 어려운 이유","서비스는 요청과 응답이 한 쌍이며 domain_bridge의 service API는 실제 C++ 서비스 타입을 템플릿으로 요구합니다. 필요한 타입을 포함한 전용 C++ 브리지나 프록시 노드를 별도로 빌드해야 할 수 있습니다.","// 서비스 타입을 컴파일 시점에 지정\ndomain_bridge.bridge_service<MyService>(\n    '/my_service', 1, 2);"],["액션이 더 어려운 이유","액션은 단일 통신이 아니라 서비스 3개와 숨김 토픽 2개가 결합된 프로토콜입니다. 일부만 연결하면 Goal이 서버를 기다리거나 결과·취소·피드백이 끊길 수 있습니다.","/<action>/_action/send_goal    # service\n/<action>/_action/get_result   # service\n/<action>/_action/cancel_goal  # service\n/<action>/_action/feedback     # topic\n/<action>/_action/status       # topic"]);
D["ros-domain-bridge"].check.push("토픽은 domain_bridge, 서비스·액션은 멀티프로세스 프록시가 유리한 이유를 설명할 수 있다");
D["mobile-robot-description"]={no:"03.08",title:"모바일 로봇 Description 패키지",lead:"Pinky Pro를 예제로 ROS 2 description 패키지의 URDF·Xacro·launch 구조를 읽고 robot_state_publisher와 RViz2로 완성된 로봇 모델을 검증합니다.",time:"100분",source:"https://drive.google.com/file/d/12eEnKOK6Co-JQ-RzraE8efQt_JzV795n/view",concepts:[["Description package","로봇의 외형, 충돌 형상, 관성, link·joint 관계와 센서 좌표계를 URDF/Xacro·mesh·launch로 묶은 패키지"],["URDF / Xacro","URDF는 XML 기반 로봇 모델이고 Xacro는 매크로·변수·조건문으로 반복 구조를 줄이는 확장 방식"],["robot_description","Xacro를 전개한 전체 URDF XML을 담아 robot_state_publisher와 RViz가 사용하는 ROS 파라미터"],["robot_state_publisher","URDF의 joint 관계와 joint_states를 바탕으로 각 link의 TF를 계산해 발행하는 노드"],["visual·collision·inertial","화면 표시 형상, 충돌 계산 형상, 질량·무게중심·관성 행렬을 각각 정의하는 link 속성"],["view와 upload launch","view는 RViz·GUI까지 한 번에 띄우는 확인용이고 upload는 description과 joint 상태를 올려 다른 도구가 사용하게 하는 배포용"]],steps:[["Pinky Pro 코드 준비","Ubuntu 24.04와 ROS 2 Jazzy 환경에서 워크스페이스를 만들고 공식 저장소를 clone합니다.","mkdir -p ~/pinky_pro/src\ncd ~/pinky_pro/src\ngit clone https://github.com/pinklab-art/pinky_pro.git"],["의존성 설치와 빌드","워크스페이스 루트에서 rosdep으로 의존성을 설치하고 colcon으로 모든 패키지를 빌드합니다.","cd ~/pinky_pro\nrosdep update\nrosdep install --from-paths src --ignore-src -r -y\ncolcon build\nsource install/setup.bash"],["Description 패키지 구조 읽기","launch·urdf·meshes·rviz 폴더가 어떤 자산을 소유하는지 먼저 확인합니다.","ros2 pkg prefix pinky_description\nfind ~/pinky_pro/src/pinky_pro/pinky_description -maxdepth 2 -type f | sort"],["view_robot.launch 실행","확인용 launch는 Xacro 전개, robot_state_publisher, joint_state_publisher_gui, RViz2를 묶어 실행합니다.","source ~/pinky_pro/install/setup.bash\nros2 launch pinky_description view_robot.launch.py"],["robot_description 확인","실행 중인 robot_state_publisher가 전체 URDF를 파라미터로 가지고 있는지 조회합니다.","ros2 param get /robot_state_publisher robot_description\nros2 node info /robot_state_publisher\nros2 topic echo /robot_description --once"],["URDF link 구조 분석","base_footprint부터 base_link, 바퀴, caster, lamp, lidar, camera, LCD까지 부모·자식 link를 joint로 연결합니다.","<link name=\"base_link\">\n  <visual>...</visual>\n  <collision>...</collision>\n  <inertial>...</inertial>\n</link>\n<joint name=\"base_joint\" type=\"fixed\">\n  <parent link=\"base_footprint\"/>\n  <child link=\"base_link\"/>\n</joint>"],["Xacro와 관성 매크로 분석","robot.urdf.xacro가 설정값을 준비하고 pinky.urdf.xacro의 로봇 매크로를 호출하며, 별도 inertia 매크로가 원기둥·직육면체·구의 관성을 계산합니다.","<xacro:include filename=\"$(find pinky_description)/urdf/pinky.urdf.xacro\"/>\n<xacro:property name=\"wheel_radius\" value=\"...\"/>\n<xacro:insert_robot ... />"],["TF와 모델 검증","RViz Fixed Frame을 base_footprint로 맞추고 TF와 RobotModel을 함께 표시해 joint 계층과 형상을 비교합니다.","rviz2\n# Fixed Frame: base_footprint\n# Add → TF\n# Add → RobotModel\nros2 run tf2_tools view_frames"],["upload.launch와 RViz 설정","upload launch로 description을 먼저 올린 뒤 RViz에서 RobotModel의 Description Topic을 설정하고, 완성한 화면 구성을 .rviz로 저장해 launch에서 재사용합니다.","ros2 launch pinky_description upload.launch.py\nrviz2\n# RobotModel → Description Source: Topic\n# Description Topic: /robot_description\n# File → Save Config As\nrviz2 -d <saved_config.rviz>"],["시뮬레이션까지 확장","description이 정상인지 확인한 뒤 Gazebo Harmonic용 패키지에서 같은 모델과 센서 구성을 시뮬레이션합니다.","ros2 launch pinky_gz_sim launch_sim.launch.xml"]],check:["pinky_description 패키지의 launch·urdf·meshes·rviz 역할을 설명할 수 있다","visual·collision·inertial의 차이를 구분할 수 있다","robot_state_publisher와 joint_state_publisher_gui의 역할 차이를 안다","RViz에서 TF와 RobotModel을 함께 확인했다","RViz 설정을 저장하고 다시 불러왔다"],quiz:["robot_state_publisher가 link별 TF를 계산하기 위해 가장 먼저 필요한 것은?","robot_description의 URDF 모델",["RViz 배경색","robot_description의 URDF 모델","Gazebo world 파일"]]};
