document.title=d.title+" · ROS2";
const esc=s=>s.replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;");
document.querySelector("#app").innerHTML=`<header><div class="shell top"><a class="brand" href="../index.html"><b>ROS</b>2 LEARN</a><a class="back" href="../index.html">← 전체 강의</a></div></header><section class="hero"><div class="shell"><div class="kicker">${d.no} · TEXTBOOK STUDY NOTE</div><h1>${d.title}</h1><p class="lead">${d.lead}</p><div class="meta"><span class="pill">예상 ${d.time}</span><span class="pill">개념 → 코드 → 검증 → 복습</span><span class="pill">ROS 2 Jazzy</span></div></div></section><div class="shell layout"><nav class="toc"></nav><article><section id="overview"><h2>무엇을 배우는가</h2><p class="lead">이 페이지는 명령을 그대로 복사하는 실습지가 아니라, 각 명령과 코드가 ROS 2 안에서 어떤 역할을 하는지 이해하도록 구성한 학습 노트입니다.</p><div class="lesson-goal"><b>이번 학습의 목표</b><span>${d.lead}</span></div><div class="flow">${d.steps.map((x,i)=>`<span><small>STEP ${String(i+1).padStart(2,"0")}</small>${x[0]}</span>`).join("")}</div></section><section id="prepare"><h2>실습 전 준비</h2><div class="prepare-grid"><div><b>환경 확인</b><p>Ubuntu와 ROS 2 Jazzy 환경을 기준으로 합니다. 새 터미널을 열었다면 먼저 ROS 환경을 불러옵니다.</p><pre><code>source /opt/ros/jazzy/setup.bash</code></pre></div><div><b>터미널 사용법</b><p>실행 상태를 유지해야 하는 노드는 서로 다른 터미널에서 실행합니다. 각 터미널에도 동일하게 source가 필요합니다.</p></div><div><b>확인 원칙</b><p>프로그램이 종료되지 않는 것만으로 성공이라 판단하지 말고 노드, 토픽, 메시지 값과 시각 결과를 함께 확인합니다.</p></div></div></section><section id="concept"><h2>핵심 개념</h2><p class="lead">코드에 들어가기 전에 아래 용어를 자신의 말로 설명할 수 있는지 확인하세요.</p><div class="concepts">${d.concepts.map(x=>`<div class="concept"><b>${x[0]}</b><span>${x[1]}</span></div>`).join("")}</div></section><section id="syntax"><h2>용어와 API 해부</h2><p class="lead">아래 표는 이번 강의에서 반복해서 만나는 구성 요소와 코드에서의 역할을 연결한 것입니다.</p><table class="study-table syntax-table"><thead><tr><th>용어/API</th><th>의미</th><th>코드에서 확인할 지점</th></tr></thead><tbody>${d.concepts.map((x,i)=>`<tr><td><code>${x[0]}</code></td><td>${x[1]}</td><td>${d.steps[Math.min(i,d.steps.length-1)][0]} 단계</td></tr>`).join("")}</tbody></table></section><section id="practice"><h2>단계별 코드와 해설</h2><div class="note">명령은 터미널마다 ROS 환경을 source한 뒤 실행하세요. 긴 타입과 필드는 Tab 자동완성을 활용하면 실수를 줄일 수 있습니다.</div>${d.steps.map((x,i)=>`<div class="step" data-n="${i+1}"><h3>${x[0]}</h3><p>${x[1]}</p><pre><code>${esc(x[2])}</code></pre><div class="code-reading"><b>코드 읽기</b><span>${x[0]} 단계의 핵심은 “${x[1]}”입니다. 실행 뒤에는 다음 단계로 넘어가기 전에 터미널의 오류 메시지와 ROS 그래프 변화를 확인하세요.</span></div></div>`).join("")}</section><section id="check"><h2>학습 체크</h2><p class="lead">아래 항목을 직접 확인했을 때만 체크하세요. 체크 결과는 이 브라우저에 저장됩니다.</p><div class="checklist">${d.check.map((x,i)=>`<label><input type="checkbox" data-check="${i}"><span>${x}</span></label>`).join("")}</div></section><section id="quiz"><h2>미니 퀴즈</h2><div class="quiz"><h3>${d.quiz[0]}</h3><div class="answers">${d.quiz[2].map(x=>`<button data-answer="${x}">${x}</button>`).join("")}</div><div class="result"></div></div><a class="quiz-more" href="../quiz.html">문제 더 풀기 →</a></section><section id="source"><h2>원본 자료와 다음 학습</h2><p class="lead">이 페이지로 흐름을 이해한 뒤 PDF 또는 원본 HTML을 나란히 열어 이미지, 터미널 출력, 발표자료의 세부 설명을 비교하세요.</p><div class="sourcebar"></div></section></article></div>`;
const algorithm=document.createElement("section");algorithm.id="algorithm";algorithm.innerHTML=`<h2>전체 알고리즘</h2><p class="lead">코드를 줄 단위로 보기 전에 프로그램이 어떤 순서로 움직이는지 먼저 잡아두세요.</p><ol class="algorithm-list">${d.steps.map((x,i)=>`<li><b>${i+1}. ${x[0]}</b><span>${x[1]}</span></li>`).join("")}</ol>`;document.querySelector("#practice").after(algorithm);
const commandPattern=/^(source|ros2|colcon|rqt|rqt_graph|rqt_plot|rqt_console|rviz2|python3|mkdir|cd|sudo)\b/;const runLines=[...new Set(d.steps.flatMap(x=>x[2].split("\n").map(y=>y.trim()).filter(y=>commandPattern.test(y))))];const run=document.createElement("section");run.id="run";run.innerHTML=`<h2>실행 순서</h2><p class="lead">아래 명령은 위 코드에서 실제 실행에 필요한 줄을 모은 것입니다. 여러 노드를 동시에 켜야 하면 새 터미널을 열고 환경을 다시 source하세요.</p><pre><code>${esc(runLines.join("\n")||"source /opt/ros/jazzy/setup.bash\n# 위 단계에서 작성한 노드를 실행하세요.")}</code></pre><div class="run-hints"><span><b>1</b> 환경 source</span><span><b>2</b> 서버·발행 노드 먼저 실행</span><span><b>3</b> 클라이언트·구독 노드 실행</span><span><b>4</b> CLI와 GUI로 결과 확인</span></div>`;algorithm.after(run);
const verify=document.createElement("section");verify.id="verify";verify.innerHTML=`<h2>실행 결과 검증</h2><p class="lead">코드가 종료되지 않았다는 것만으로 성공이라고 판단하지 않습니다. ROS 그래프, 메시지 값, 시각 결과를 각각 확인하세요.</p><table class="study-table"><thead><tr><th>검증 대상</th><th>명령 또는 도구</th><th>정상 기준</th></tr></thead><tbody>${extra.verify.map(x=>`<tr><td>${x[0]}</td><td><code>${esc(x[1])}</code></td><td>${x[2]}</td></tr>`).join("")}</tbody></table>`;run.after(verify);
const troubleshooting=document.createElement("section");troubleshooting.id="trouble";troubleshooting.innerHTML=`<h2>자주 겪는 문제와 해결</h2>${extra.trouble.map(x=>`<details class="trouble"><summary>${x[0]}</summary><p>${x[1]}</p></details>`).join("")}`;verify.after(troubleshooting);
const practiceMore=document.createElement("section");practiceMore.id="challenge";practiceMore.innerHTML=`<h2>응용 실습</h2><p class="lead">그대로 따라 한 뒤에는 값을 바꾸고 구조를 확장해야 자기 지식이 됩니다.</p><div class="challenges">${extra.challenge.map(x=>`<div class="challenge">${x}</div>`).join("")}</div>`;troubleshooting.after(practiceMore);
const review=document.createElement("section");review.id="review";review.innerHTML=`<h2>복습 문제</h2><p class="lead">답을 바로 펼치기 전에 말이나 메모로 먼저 설명해보세요.</p><div class="review-list">${d.concepts.map((x,i)=>`<details class="review-question"><summary>Q${i+1}. ${x[0]}은 무엇이며 이번 실습에서 왜 필요한가?</summary><p><b>모범 답안:</b> ${x[1]} 이번 강의에서는 ${d.steps[Math.min(i,d.steps.length-1)][0]} 과정과 연결해 이해할 수 있습니다.</p></details>`).join("")}<details class="review-question"><summary>Q${d.concepts.length+1}. 이번 실습이 정상 동작했다고 판단할 근거를 두 가지 이상 말해보세요.</summary><p><b>모범 답안:</b> ${extra.verify.map(x=>`${x[0]}에서 ${x[2]}`).join("; ")} 등을 함께 확인합니다.</p></details></div>`;document.querySelector("#check").after(review);
document.querySelector(".toc").innerHTML='<b>LESSON MAP</b><a href="#overview">01 학습 목표·전체 흐름</a><a href="#prepare">02 실습 전 준비</a><a href="#concept">03 핵심 개념</a><a href="#syntax">04 용어·API 해부</a><a href="#practice">05 코드와 해설</a><a href="#algorithm">06 전체 알고리즘</a><a href="#run">07 실행 순서</a><a href="#verify">08 결과 검증</a><a href="#trouble">09 오류 해결</a><a href="#challenge">10 응용 실습</a><a href="#check">11 학습 체크</a><a href="#review">12 복습 문제</a><a href="#quiz">13 미니 퀴즈</a><a href="#source">14 원본 자료</a>';
const pdfId=PDF[id],pdfView=`https://drive.google.com/file/d/${pdfId}/view`,pdfDownload=`https://drive.google.com/uc?export=download&id=${pdfId}`;document.querySelector(".sourcebar").innerHTML=`<a class="button pdf" target="_blank" rel="noopener" href="${pdfView}">PDF로 열기</a><a class="button secondary" target="_blank" rel="noopener" href="${HTML[id]}">원본 HTML 열기</a><a class="button secondary" target="_blank" rel="noopener" href="${pdfDownload}">PDF 다운로드</a><a class="button secondary" href="../index.html">전체 목차</a>`;
document.querySelectorAll("pre").forEach(pre=>{const button=document.createElement("button");button.className="code-copy";button.type="button";button.textContent="복사";button.onclick=async()=>{try{await navigator.clipboard.writeText(pre.querySelector("code")?.textContent||pre.textContent);button.textContent="복사됨";setTimeout(()=>button.textContent="복사",1200)}catch{button.textContent="선택 후 복사"}};pre.append(button)});
const progressKey="lesson-"+id;const checks=[...document.querySelectorAll("[data-check]")];const saved=JSON.parse(localStorage.getItem(progressKey)||"[]");checks.forEach((x,i)=>{x.checked=!!saved[i];x.onchange=()=>localStorage.setItem(progressKey,JSON.stringify(checks.map(y=>y.checked)))});
document.querySelectorAll("[data-answer]").forEach(b=>b.onclick=()=>{const ok=b.dataset.answer===d.quiz[1];document.querySelectorAll("[data-answer]").forEach(x=>x.classList.remove("good","bad"));b.classList.add(ok?"good":"bad");document.querySelector(".result").textContent=ok?"정답입니다. 개념을 실제 명령과 연결해보세요.":"다시 생각해보세요. 위의 핵심 개념과 실습 결과를 확인해보세요."});
